import java.io.Serializable;

public class TaskEvent implements Serializable {

    public static final int EVENT_SUBMIT = 0;

    public long timestamp;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public static TaskEvent fromCsv(String line) {
        // task_events schema (v2.1):
        // 0 timestamp, 1 missing_info, 2 job_id, 3 task_index, 4 machine_id,
        // 5 event_type, ...
        String[] f = line.split(",", -1);
        if (f.length < 6 || f[0].isEmpty() || f[2].isEmpty() || f[3].isEmpty() || f[5].isEmpty()) {
            return null;
        }
        long ts = Long.parseLong(f[0]);
        long jobId = Long.parseLong(f[2]);
        long taskIdx = Long.parseLong(f[3]);
        int eventType = Integer.parseInt(f[5]);
        return new TaskEvent(ts, jobId, taskIdx, eventType);
    }
}
