import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

public class GzipCsvSourceFunction<T> implements SourceFunction<T> {

    public interface Parser<T> extends java.io.Serializable {
        T parse(String line) throws Exception;
    }

    private final String path;
    private final Parser<T> parser;

    private volatile boolean running = true;

    public GzipCsvSourceFunction(String path, Parser<T> parser) {
        this.path = path;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (InputStream fis = new FileInputStream(path);
             InputStream is = path.endsWith(".gz") ? new GZIPInputStream(fis) : fis;
             BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = br.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }
                T parsed;
                try {
                    parsed = parser.parse(line);
                } catch (Exception e) {
                    // skip malformed records
                    continue;
                }
                if (parsed != null) {
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(parsed);
                    }
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
