", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.io.GzipCsvSourceFunction;
import clusterdata.io.LocalTextFileSink;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.util.Collector;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required params: --task_input --job_input --output");
        }

        long gapMicros = sesssize * 1_000_000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> tasks = env.addSource(
                taskSourceOrTest(new GzipCsvSourceFunction<>(taskInput, TaskEvent::fromCsv))
        );

        DataStream<JobEvent> jobs = env.addSource(
                jobSourceOrTest(new GzipCsvSourceFunction<>(jobInput, JobEvent::fromCsv))
        );

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestamp);

        WatermarkStrategy<JobEvent> jobWm = WatermarkStrategy
                .<JobEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestamp);

        KeyedStream<TaskEvent, Long> keyedTaskSubmits = tasks
                .filter(t -> t.eventType == TaskEvent.EVENT_SUBMIT)
                .assignTimestampsAndWatermarks(taskWm)
                .keyBy(TaskEvent::getJobId);

        KeyedStream<JobEvent, Long> keyedJobFinishes = jobs
                .filter(j -> j.eventType == JobEvent.EVENT_FINISH)
                .assignTimestampsAndWatermarks(jobWm)
                .keyBy(JobEvent::getJobId);

        DataStream<Tuple2<Long, Integer>> longestStagePerFinishedJob = keyedTaskSubmits
                .connect(keyedJobFinishes)
                .process(new LongestStageOnFinish(gapMicros));

        longestStagePerFinishedJob
                .map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .addSink(sinkOrTest(new LocalTextFileSink(outputPath)))
                .name("local-file-sink")
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static class LongestStageOnFinish
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {

        private final long gapMicros;

        private transient ValueState<Long> lastSubmitTs;
        private transient ValueState<Integer> currentStageCount;
        private transient ValueState<Integer> maxStageCount;
        private transient ValueState<Long> finishTs;
        private transient ValueState<Boolean> emitted;

        private LongestStageOnFinish(long gapMicros) {
            this.gapMicros = gapMicros;
        }

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            lastSubmitTs = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTs", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            finishTs = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTs", Long.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Long finish = finishTs.value();
            if (finish != null && value.timestamp > finish) {
                return;
            }

            Long last = lastSubmitTs.value();
            Integer cur = currentStageCount.value();
            Integer max = maxStageCount.value();

            if (cur == null) {
                cur = 0;
            }
            if (max == null) {
                max = 0;
            }

            if (last != null && value.timestamp - last > gapMicros) {
                if (cur > max) {
                    max = cur;
                }
                cur = 0;
            }

            cur += 1;

            lastSubmitTs.update(value.timestamp);
            currentStageCount.update(cur);
            maxStageCount.update(max);
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Long alreadyEmitted = emitted.value();
            if (alreadyEmitted != null && alreadyEmitted) {
                return;
            }

            Long existingFinish = finishTs.value();
            if (existingFinish == null || value.timestamp < existingFinish) {
                finishTs.update(value.timestamp);
                ctx.timerService().registerEventTimeTimer(value.timestamp);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Boolean alreadyEmitted = emitted.value();
            if (alreadyEmitted != null && alreadyEmitted) {
                return;
            }

            Integer cur = currentStageCount.value();
            Integer max = maxStageCount.value();
            if (cur == null) {
                cur = 0;
            }
            if (max == null) {
                max = 0;
            }
            if (cur > max) {
                max = cur;
            }

            out.collect(Tuple2.of(ctx.getCurrentKey(), max));
            emitted.update(true);
        }
    }
}
